import functools

def tag(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        return fn(*args, **kwargs)
    return wrapper

@tag
def greet(name):
    """Say hello."""
    return f"Hello, {name}"

print(greet.__name__)

def twice(fn):
    def wrapper(*args, **kwargs):
        return fn(*args, **kwargs)
    return wrapper

@twice
def add(a, b):
    return a + b

print(add(2, 3))
